SELECT COUNT(*) AS films_with_high_replacement FROM film WHERE replacement_cost > 25.00;
SELECT COUNT(*) AS films_with_low_rate FROM film WHERE rental_rate < 1.00;
SELECT COUNT(*) AS films_matching_both FROM film WHERE replacement_cost > 25.00 AND rental_rate < 1.00;
"}

{"query": "
